import os
from typing import Any, Dict, List, Optional

from azure.ai.formrecognizer import DocumentAnalysisClient
from azure.core.credentials import AzureKeyCredential


def _first_non_empty(*values):
    for v in values:
        if v is not None and v != "":
            return v
    return None


def _field_value(field: Any) -> Any:
    if field is None:
        return None
    for attr in (
        "value",
        "content",
        "value_string",
        "value_date",
        "value_time",
        "value_phone_number",
        "value_country_region",
        "value_selection_mark",
        "value_signature",
        "value_integer",
        "value_number",
        "value_currency",
        "value_address",
    ):
        if hasattr(field, attr):
            val = getattr(field, attr)
            if val is not None:
                if attr == "value_currency":
                    amount = getattr(val, "amount", None)
                    currency = getattr(val, "currency_code", None)
                    return {"amount": amount, "currency_code": currency}
                if attr == "value_address":
                    return {
                        "street_address": getattr(val, "street_address", None),
                        "city": getattr(val, "city", None),
                        "state": getattr(val, "state", None),
                        "postal_code": getattr(val, "postal_code", None),
                        "country_region": getattr(val, "country_region", None),
                    }
                return val
    return None


def _currency_amount(field: Any) -> Optional[float]:
    if field is None:
        return None
    if hasattr(field, "value_currency") and field.value_currency is not None:
        return getattr(field.value_currency, "amount", None)
    value = _field_value(field)
    if isinstance(value, dict) and "amount" in value:
        return value["amount"]
    if isinstance(value, (int, float)):
        return float(value)
    return None


def _parse_line_item(item_field: Any) -> Dict[str, Any]:
    result: Dict[str, Any] = {
        "description": None,
        "quantity": None,
        "unit": None,
        "unit_price": None,
        "product_code": None,
        "date": None,
        "tax": None,
        "amount": None,
    }

    if item_field is None or not hasattr(item_field, "value_object") or item_field.value_object is None:
        return result

    obj = item_field.value_object

    result["description"] = _field_value(obj.get("Description"))
    qty = _field_value(obj.get("Quantity"))
    result["quantity"] = float(qty) if isinstance(qty, (int, float)) else qty
    result["unit"] = _field_value(obj.get("Unit"))
    result["unit_price"] = _currency_amount(obj.get("UnitPrice"))
    result["product_code"] = _field_value(obj.get("ProductCode"))
    result["date"] = _field_value(obj.get("Date"))
    result["tax"] = _currency_amount(obj.get("Tax"))
    result["amount"] = _currency_amount(obj.get("Amount"))

    return result


def extract_invoice_fields(file_path: str) -> Dict[str, Any]:
    endpoint = os.environ["AZURE_FORM_RECOGNIZER_ENDPOINT"]
    api_key = os.environ["AZURE_FORM_RECOGNIZER_KEY"]

    client = DocumentAnalysisClient(
        endpoint=endpoint,
        credential=AzureKeyCredential(api_key),
    )

    with open(file_path, "rb") as f:
        poller = client.begin_analyze_document(
            model_id="prebuilt-invoice",
            document=f,
        )
    result = poller.result()

    if not result.documents:
        return {
            "vendor": None,
            "date": None,
            "total": None,
            "line_items": [],
        }

    doc = result.documents[0]
    fields = doc.fields or {}

    vendor = _first_non_empty(
        _field_value(fields.get("VendorName")),
        _field_value(fields.get("CustomerName")),
    )
    date = _first_non_empty(
        _field_value(fields.get("InvoiceDate")),
        _field_value(fields.get("DueDate")),
    )
    total = _currency_amount(fields.get("InvoiceTotal"))

    line_items: List[Dict[str, Any]] = []
    items_field = fields.get("Items")
    if items_field is not None and hasattr(items_field, "value_array") and items_field.value_array:
        line_items = [_parse_line_item(item) for item in items_field.value_array]

    return {
        "vendor": vendor,
        "date": str(date) if date is not None else None,
        "total": total,
        "line_items": line_items,
    }
